<?php
namespace App\Http\Controllers; use App\Models\{Purchase,Item,PurchaseItem,PurchasePayment,StockMovement}; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Validation\ValidationException;
class PurchaseController extends Controller {public function index(){return view('purchases.index',['purchases'=>Purchase::with('items.item')->latest('purchase_date')->paginate(20)]);} public function create(){return view('purchases.form',['items'=>Item::orderBy('name')->get()]);} public function store(Request $r){$d=$r->validate(['purchase_date'=>'required|date','supplier_name'=>'nullable|string|max:255','item_id'=>'required|exists:items,id','quantity'=>'required|integer|min:1','unit_cost'=>'required|numeric|min:0','paid_amount'=>'required|numeric|min:0','notes'=>'nullable|string']);DB::transaction(function()use($d){$item=Item::lockForUpdate()->findOrFail($d['item_id']);$total=$d['quantity']*$d['unit_cost'];if($d['paid_amount']>$total)throw ValidationException::withMessages(['paid_amount'=>'Payment total se zyada nahi ho sakti.']);$p=Purchase::create(['purchase_no'=>'PUR-'.now()->format('ymdHis').'-'.random_int(10,99),'purchase_date'=>$d['purchase_date'],'subtotal'=>$total,'paid_amount'=>$d['paid_amount'],'total'=>$total,'notes'=>trim(($d['supplier_name']??'').' '.($d['notes']??''))]);PurchaseItem::create(['purchase_id'=>$p->id,'item_id'=>$item->id,'quantity'=>$d['quantity'],'unit_cost'=>$d['unit_cost'],'line_total'=>$total]);$item->increment('quantity',$d['quantity']);$item->update(['buying_price'=>$d['unit_cost']]);StockMovement::create(['item_id'=>$item->id,'movement_type'=>'purchase','quantity'=>$d['quantity'],'reference'=>$p->purchase_no,'movement_date'=>$d['purchase_date']]);if($d['paid_amount']>0)PurchasePayment::create(['purchase_id'=>$p->id,'payment_date'=>$d['purchase_date'],'amount'=>$d['paid_amount'],'method'=>'Cash']);});return redirect('/purchases')->with('success','Purchase aur stock update ho gaya.');} public function payment(Request $r,Purchase $purchase){$d=$r->validate(['payment_date'=>'required|date','amount'=>'required|numeric|min:0.01','method'=>'required|string|max:40','notes'=>'nullable|string']);if($d['amount']>$purchase->total-$purchase->paid_amount)throw ValidationException::withMessages(['amount'=>'Payment due se zyada hai.']);DB::transaction(function()use($d,$purchase){$purchase->payments()->create($d);$purchase->increment('paid_amount',$d['amount']);});return back()->with('success','Supplier payment save ho gayi.');}}
